extern "c" fn GlobalUnlock(h: *anyopaque) callconv(.winapi) c_int;

pub fn factory() WicError!*IWICImagingFactory {
        if ((!com_initialised)) {
            if ((CoInitializeEx(null, COINIT_MULTITHREADED) < 0)) {
                return error.BackendUnavailable;
            }
            com_initialised = true;
        }
        _ = factory_once.call();
        if (factory_ptr) |p| {
            _ = &p;
            return p;
        }
        return error.BackendUnavailable;
}

pub fn loadFactory() void {
        const dll = bun.windows.LoadLibraryA("windowscodecs.dll");
        if ((dll == null)) {
            return;
        }
        const sym = bun.windows.GetProcAddressA(dll.?, "WICConvertBitmapSource");
        if ((sym == null)) {
            return;
        }
        wicConvertBitmapSource = @ptrCast(@alignCast(sym.?));
        var out: ?*anyopaque = null;
        _ = &out;
        if ((CoCreateInstance(*const CLSID_WICImagingFactory, null, CLSCTX_INPROC_SERVER, *const IID_IWICImagingFactory, (&out)) < 0)) {
            return;
        }
        factory_ptr = @ptrCast(@alignCast(out));
}

extern "c" fn OpenClipboard(hwnd: ?*anyopaque) callconv(.winapi) c_int;

extern "c" fn CloseClipboard() callconv(.winapi) c_int;

extern "c" fn IsClipboardFormatAvailable(format: c_uint) callconv(.winapi) c_int;

extern "c" fn GetClipboardData(format: c_uint) callconv(.winapi) ?*anyopaque;

extern "c" fn RegisterClipboardFormatA(name: [*:0]u8) callconv(.winapi) c_uint;

extern "c" fn GetClipboardSequenceNumber() callconv(.winapi) u32;

extern "c" fn GlobalSize(h: *anyopaque) callconv(.winapi) usize;

pub fn clipboardChangeCount() i64 {
        return GetClipboardSequenceNumber();
}

pub fn hasClipboardImage() bool {
        if (((IsClipboardFormatAvailable(CF_DIBV5) != 0) or (IsClipboardFormatAvailable(CF_DIB) != 0))) {
            return true;
        }
        for (cp_iter_slice(named_formats)) |name| {
            _ = &name;
            const id = RegisterClipboardFormatA(name);
            if (((id != 0) and (IsClipboardFormatAvailable(id) != 0))) {
                return true;
            }
        }
        return false;
}

pub fn clipboard() WicError!?[]u8 {
        if ((OpenClipboard(null) == 0)) {
            return error.BackendUnavailable;
        }
        defer {
        _ = CloseClipboard();
        }
        for (cp_iter_slice(named_formats)) |name| {
            _ = &name;
            const id = RegisterClipboardFormatA(name);
            if ((id != 0)) {
                if (GetClipboardData(id)) |h| {
                    _ = &h;
                    if (try dupGlobal(h, 0)) |b| {
                        _ = &b;
                        return b;
                    }
                }
            }
        }
        const cfs: [2]c_uint = .{ CF_DIBV5, CF_DIB };
        for (cp_iter_slice(cfs)) |cf| {
            _ = &cf;
            if (GetClipboardData(cf)) |h| {
                _ = &h;
                if (try dupGlobal(h, 14)) |*buf| {
                    _ = &buf;
                    if ((((buf.*).len < (14 + 40)) or ((buf.*).len > std.math.maxInt(u32)))) {
                        _ = bun.default_allocator.free((buf.*));
                        continue;
                    }
                    const ih_size: u64 = std.mem.readInt(u32, (buf.*)[14..18], .little);
                    const compression = std.mem.readInt(u32, (buf.*)[(14 + 16)..][0..4], .little);
                    const masks: u64 = (if (((ih_size == 40) and (compression == 3))) (if (comptime @typeInfo(@TypeOf(12)) == .@"enum") cp_cast_int(u64, @intFromEnum(12)) else cp_cast_int(u64, 12)) else (if (comptime @typeInfo(@TypeOf(0)) == .@"enum") cp_cast_int(u64, @intFromEnum(0)) else cp_cast_int(u64, 0)));
                    const off = ((14 + ih_size) + masks);
                    if (((ih_size < 40) or (off > (buf.*).len))) {
                        _ = bun.default_allocator.free((buf.*));
                        continue;
                    }
                    (buf.*)[cp_cast_int(usize, 0)] = 66;
                    (buf.*)[cp_cast_int(usize, 1)] = 77;
                    _ = std.mem.writeInt(u32, (buf.*)[2..6], @intCast((buf.*).len), .little);
                    _ = std.mem.writeInt(u32, (buf.*)[6..10], 0, .little);
                    _ = std.mem.writeInt(u32, (buf.*)[10..14], @intCast(off), .little);
                    return (buf.*);
                }
            }
        }
        return null;
}

pub fn dupGlobal(h: *anyopaque, comptime prefix: usize) WicError!?[]u8 {
        const size = GlobalSize(h);
        if ((size == 0)) {
            return null;
        }
        const lk = GlobalLock(h);
        if ((lk == null)) {
            return null;
        }
        const ptr: [*]const u8 = @ptrCast(lk.?);
        defer {
        _ = GlobalUnlock(h);
        }
        const out = try bun.default_allocator.alloc(u8, (prefix + size));
        _ = @memcpy(out[prefix..], (blk: {
        break :blk ptr[0..size];

}));
        return out;
}
